package com.estradaplay.patriota;
import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import java.util.*;
public final class RoadFavoritesActivity extends ComponentActivity{private LinearLayout page;private int TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38);@Override protected void onCreate(Bundle b){super.onCreate(b);build();}private void build(){ScrollView sv=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(28));page.setBackgroundColor(Color.rgb(9,5,7));sv.addView(page);setContentView(UnifiedAppShell.wrap(this,"trip",sv));page.addView(t("FAVORITOS DA ESTRADA",27,TEXT,true));page.addView(t("Postos, oficinas, hospitais e paradas salvos no aparelho.",12,MUTED,false));ArrayList<FavoriteRoadStore.Item>a=FavoriteRoadStore.list(this);if(a.isEmpty())page.addView(t("Nenhum favorito ainda. Salve pela tela Serviços na Estrada.",14,MUTED,false));for(FavoriteRoadStore.Item x:a){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);Button go=new Button(this);go.setAllCaps(false);go.setText(x.name+"\n"+x.type);go.setOnClickListener(v->{DestinationStore.save(this,new DestinationStore.Destination(x.name,x.lat,x.lon));startActivity(new Intent(this,RoadMapActivity.class));});Button del=new Button(this);del.setText("REMOVER");del.setOnClickListener(v->{FavoriteRoadStore.remove(this,x.lat,x.lon);build();});r.addView(go,new LinearLayout.LayoutParams(0,dp(66),1));r.addView(del,new LinearLayout.LayoutParams(dp(105),dp(66)));page.addView(r);} }private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(android.graphics.Typeface.DEFAULT,android.graphics.Typeface.BOLD);return t;}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}}
